/* From Uiverse.io by JaydipPrajapati1910 - Tags: neumorphism, input */
.__UIV_SCOPE__ .input {
  max-width: 190px;
  border: none;
  outline: none;
  background: none;
  font-size: 18px;
  color: #555;
  padding: 15px 5px 10px 20px;
  box-shadow: inset 8px 8px 8px #cbced1,
              inset -8px -8px 8px #ffffff;
  border-radius: 25px;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #555;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  color: #999;
}
